def clear_acl_graph_params(params: Any) -> None:
    """Clear all ACL graph parameters for sleep mode cleanup."""
    # 逐个属性重复清理代码 — 每个属性使用相同的循环模式
    for num_tokens in list(params.events.keys()):
        params.events[num_tokens] = []
    for num_tokens in list(params.handles.keys()):
        params.handles[num_tokens] = []
    for num_tokens in list(params.attn_params.keys()):
        params.attn_params[num_tokens] = []
    for num_tokens in list(params.conv1d_params.keys()):
        params.conv1d_params[num_tokens] = []
    for num_tokens in list(params.conv1d_handles.keys()):
        params.conv1d_handles[num_tokens] = []
    for num_tokens in list(params.conv1d_events.keys()):
        params.conv1d_events[num_tokens] = []
